Definition atx_table1 (m : mem) (p1 p2 : list byte) (f1 a1 : word) : Prop :=
  rw_cells asegs m ATX_S [C1 (Z_to_bv 8 0); CB 3 p1; C4 (Z_to_bv 64 0); C4 (Z_to_bv 64 1); CB 4 p2; C8 (Z_to_bv 64 ATX_BUILTIN);
                          C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 ATX_CALL); C8 f1]
  /\ rw_cells asegs m ATX_A0 [C8 (Z_to_bv 64 COV_DUMP); C8 a1].
Definition atx_table2 (m : mem) (p1 p2 : list byte) : Prop :=
  rw_cells asegs m ATX_S [C1 (Z_to_bv 8 0); CB 3 p1; C4 (Z_to_bv 64 0); C4 (Z_to_bv 64 2); CB 4 p2; C8 (Z_to_bv 64 ATX_BUILTIN);
                          C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 ATX_CALL); C8 (Z_to_bv 64 ATX_CALL)]
  /\ rw_cells asegs m ATX_A0 [C8 (Z_to_bv 64 COV_DUMP); C8 (Z_to_bv 64 AEF_GUARD)].
Definition XENV_trA (m : mem) : Prop :=
  rw_cells asegs m TR_INCB [C1 (Z_to_bv 8 0)]
  /\ exists p1 p2 : list byte,
       (rw_cells asegs m TR_INIT [C1 (Z_to_bv 8 0)] /\ exists f1 a1 : word, atx_table1 m p1 p2 f1 a1)
       \/ (rw_cells asegs m TR_INIT [C1 (Z_to_bv 8 1)] /\ atx_table2 m p1 p2).
Definition XENVA (m : mem) : Prop := XENV_coreA m /\ XENV_trA m.

